# .scoped-gates.map: change-scoped gates (format: quota-aware-verified-swarm
# references/scoped_gates_map.md). Unmapped paths escalate to the full run,
# so no catch-all glob covers new files under src/, src/bin/, tests/ or specs/.
# test = suites importing the module + suites spawning a binary (parvault,
#   parvault-seed) whose `use` closure reaches it + runtime callers.
# lib  = the module's own unit tests + those of every module that depends on
#   it (transitive `use` edges in src/); no filter that matches 0 tests.
# tla_formal_proofs_integration (all 7 TLC specs) is kept only for its own
# file, bootstrap.rs and sync.rs: its lite-client failover test is the only
# suite driving LiteRestoreRoute. Other modules map to their specific specs.

# --- Crate-wide blast radius -> full -----------------------------------------
src/lib.rs                      full    # module tree, crate attrs, cfg(kani)
# Binary-only code (main.rs, src/cli/*): cannot change a Kani or TLC result; it is
# gated by the suites that spawn `parvault` (clippy runs only in full mode).
# Until the runner has a scoped clippy step, a scoped run on these paths must be
# followed by `cargo clippy --all-targets -- -D warnings`.
# Every `Commands` subcommand is spawned by one of these suites except `evict` and
# `list-snapshot`, which no suite runs (compile only).
src/main.rs                     test    gateway_bus_and_plugin_security
src/main.rs                     test    sync_daemon_usability_and_cli_regression_tests
src/main.rs                     test    zero_config_lan_and_router_soc_tests
src/main.rs                     test    trust_enforcement
src/cli/*                       test    gateway_bus_and_plugin_security
src/cli/*                       test    sync_daemon_usability_and_cli_regression_tests
src/cli/*                       test    zero_config_lan_and_router_soc_tests
src/cli/*                       test    trust_enforcement
src/config.rs                   full    # Cli, ErasureTier, stripe layout used crate-wide
src/crypto/*                    full    # crypto paths
src/os_sys.rs                   full    # sole unsafe FFI boundary; needs clippy
src/crypto/aes.rs               kani    proof_stripe_nonce_injectivity_and_no_panic
src/crypto/pqc.rs               tla     specs/ParVaultPostQuantum.tla
src/crypto/pqc.rs               tla     specs/ParVaultAnonymity.tla
src/config.rs                   kani    proof_streaming_stripe_layout_all_u64_file_sizes_and_profiles
src/config.rs                   kani    proof_router_soc_and_desktop_reed_solomon_memory_ceiling
src/profile.rs                  full    # ErasureTier, stripe layout (moved from config.rs), used crate-wide
src/profile.rs                  kani    proof_streaming_stripe_layout_all_u64_file_sizes_and_profiles
src/profile.rs                  kani    proof_router_soc_and_desktop_reed_solomon_memory_ceiling

